/* ---------- UI feedback ---------- */
function toast(msg,label,undo){var root=$('#toast-root');toastUndo=typeof undo==='function'?undo:null;root.innerHTML='<div class="toast" role="status"><span>'+esc(msg)+'</span>'+(toastUndo&&label?'<button id="toast-action">'+esc(label)+'</button>':'')+'</div>';clearTimeout(toastTimer);toastTimer=setTimeout(function(){root.innerHTML='';toastUndo=null},toastUndo?6500:3500)}
function applyTheme(){var t=db.settings.theme||'cabina';if(t==='dark')t='cabina';if(t==='light')t='sol';if(t==='auto')t=matchMedia('(prefers-color-scheme:light)').matches?'sol':'cabina';document.documentElement.dataset.theme=t;var meta=$('#theme-color-meta');if(meta)meta.content=t==='sol'?'#F3ECE6':'#060304'}
function transition(fn){if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion:reduce)').matches)return document.startViewTransition(fn);fn()}
function fmtTime(ts){try{return new Date(ts||Date.now()).toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'})}catch(e){return''}}
function carName(v){return[v.marca,v.modelo,v.version].filter(Boolean).join(' ')||'Vehículo'}
function identityVal(v,key){var m=(v&&v.manualIdentity)||{};return String(m[key]||v[key]||'').trim()}
function effectiveVehicle(v){v=v||cur;var out=Object.assign({},v);['chasis','motor','cilindrada','version','transmision'].forEach(function(k){var val=identityVal(v,k);if(val)out[k]=val});out.codigoMotor=String(((v.manualIdentity)||{}).codigoMotor||'').trim();return out}
function manualIdentityField(label,key,providerValue,placeholder){var m=cur.manualIdentity||{},manual=String(m[key]||''),provider=String(providerValue||'');var value=manual||provider;var note=manual?'Confirmado manualmente. Este valor tiene prioridad para IA y repuestos.':provider?'Dato del proveedor. Puedes corregirlo si tienes el VIN, catálogo o dato físico.':'Sin dato del proveedor. Agrégalo si lo tienes.';return'<div class="field identity-field"><label>'+esc(label)+'</label><input id="identity-'+key+'" value="'+esc(value)+'" placeholder="'+esc(placeholder||'')+'"><small class="identity-source '+(manual?'confirmed':'')+'">'+esc(note)+'</small></div>'}

